/**
 * Meeting method catalog.
 *
 * `kind` records how a join location is actually produced, so the editor can
 * tell the truth about each option instead of offering identical-looking
 * choices with different real capabilities:
 *
 *  - "in_person"  — a saved workspace location, no join link
 *  - "phone"      — the customer's phone number, collected at booking
 *  - "native"     — Transovo Video generates the room automatically
 *  - "calendar"   — the link is generated by a connected calendar provider
 *  - "link"       — the host supplies a reusable join URL
 */
export type MeetingMethodKind = "in_person" | "phone" | "native" | "calendar" | "link";

export type MeetingMethodDef = {
  /** Stored verbatim in config.location — existing rows rely on these strings. */
  value: string;
  label: string;
  helper: string;
  kind: MeetingMethodKind;
  /** Calendar provider that must be connected for "calendar" methods. */
  provider?: "google" | "microsoft";
};

export const MEETING_METHODS: MeetingMethodDef[] = [
  {
    value: "Transovo Video",
    label: "Transovo Video",
    helper: "Built in. A room is created for every booking.",
    kind: "native",
  },
  {
    value: "Google Meet",
    label: "Google Meet",
    helper: "Link generated by your connected Google calendar.",
    kind: "calendar",
    provider: "google",
  },
  {
    value: "Microsoft Teams",
    label: "Microsoft Teams",
    helper: "Link generated by your connected Microsoft calendar.",
    kind: "calendar",
    provider: "microsoft",
  },
  {
    value: "Zoom",
    label: "Zoom",
    helper: "Share your personal Zoom room link.",
    kind: "link",
  },
  {
    value: "Webex",
    label: "Webex",
    helper: "Share your personal Webex room link.",
    kind: "link",
  },
  {
    value: "Custom meeting link",
    label: "Custom link",
    helper: "Any other conferencing tool you already use.",
    kind: "link",
  },
  {
    value: "In person",
    label: "In person",
    helper: "Meet at one of your saved locations.",
    kind: "in_person",
  },
  {
    value: "Phone call",
    label: "Phone call",
    helper: "You call the number collected at booking.",
    kind: "phone",
  },
];

export function methodDef(value: string | undefined | null): MeetingMethodDef | null {
  if (!value) return null;
  return MEETING_METHODS.find((m) => m.value === value) || null;
}

export function methodRequiresLink(value: string | undefined | null): boolean {
  return methodDef(value)?.kind === "link";
}

/**
 * A method is only "ready" when the thing that produces its join location is
 * actually present — otherwise the meeting would publish with no way to join.
 */
export function methodIsConfigured(
  value: string | undefined | null,
  form: { meetingLink?: string; locationId?: string },
): boolean {
  const def = methodDef(value);
  if (!def) return false;
  if (def.kind === "link") return Boolean(form.meetingLink?.trim());
  if (def.kind === "in_person") return Boolean(form.locationId?.trim());
  return true;
}

export function isValidMeetingLink(value: string): boolean {
  const trimmed = value.trim();
  if (!trimmed) return false;
  try {
    const url = new URL(trimmed);
    return url.protocol === "https:" || url.protocol === "http:";
  } catch {
    return false;
  }
}
